-- Synthetic UI fixtures. Loaded only into a disposable SQLite database.
PRAGMA foreign_keys=OFF;
CREATE TABLE "achievements" ("id" integer primary key autoincrement not null, "user_id" integer not null, "course_id" integer not null, "task_id" integer not null, "solution_id" integer, "source" varchar not null default 'ai_task_solution', "status" varchar not null default 'published', "title" varchar not null, "description" text not null, "payload" text, "published_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("course_id") references "courses"("id") on delete cascade, foreign key("task_id") references "tasks"("id") on delete cascade, foreign key("solution_id") references "solutions"("id") on delete set null);
CREATE TABLE action_log (id INTEGER PRIMARY KEY, user_id INTEGER, type TEXT, object_id INTEGER, created_at TEXT, updated_at TEXT);
CREATE TABLE "ai_settings" ("id" integer not null, "settings" text not null, "updated_by" integer, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE answers (
    user_id integer,
    variant_id integer,
    created_at TEXT,
    updated_at TEXT,
    question_id integer
);
CREATE TABLE blocked_tasks (
    id INTEGER PRIMARY KEY ,
    task_id integer ,
    user_id integer ,
    course_id integer ,
    reason text,
    blocked_at TEXT,
    created_at TEXT,
    updated_at TEXT
);
CREATE TABLE code_task_tests (
    id INTEGER PRIMARY KEY ,
    input text ,
    output text ,
    is_demo text DEFAULT '1' ,
    is_shown text DEFAULT '1' ,
    task_id integer,
    created_at TEXT,
    updated_at TEXT
);
CREATE TABLE coin_transactions (
    id INTEGER PRIMARY KEY ,
    user_id integer ,
    price integer ,
    comment TEXT,
    created_at TEXT,
    updated_at TEXT
);
CREATE TABLE completed_courses (
    id INTEGER PRIMARY KEY ,
    name TEXT ,
    mark TEXT,
    user_id integer,
    course_id integer,
    cert_link TEXT
);
CREATE TABLE "course_activities" ("id" integer primary key autoincrement not null, "course_id" integer, "lesson_id" integer, "step_id" integer, "task_id" integer, "solution_id" integer, "user_id" integer, "type" varchar not null, "payload" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE course_categories (
    id INTEGER PRIMARY KEY ,
    title TEXT ,
    short_description TEXT,
    description text,
    card_image_url TEXT,
    head_image_url TEXT,
    small_image_url TEXT,
    video_url TEXT,
    created_at TEXT,
    updated_at TEXT,
    is_available boolean DEFAULT false
);
CREATE TABLE course_course_category (
    id INTEGER PRIMARY KEY ,
    course_id integer ,
    category_id integer ,
    created_at TEXT,
    updated_at TEXT
);
CREATE TABLE course_student_points (
    id INTEGER PRIMARY KEY ,
    course_id integer ,
    student_id integer ,
    points integer DEFAULT 0 ,
    max_points integer DEFAULT 0 ,
    percent REAL DEFAULT '0' ,
    created_at TEXT,
    updated_at TEXT
);
CREATE TABLE "course_students" ("user_id" integer, "course_id" integer, "created_at" text, "updated_at" text, "is_remote" boolean default (false), "hidden_from_stats" tinyint(1) not null default '0');
CREATE TABLE course_teachers (
    user_id integer,
    course_id integer,
    created_at TEXT,
    updated_at TEXT
, "hidden_from_stats" tinyint(1) not null default '0');
CREATE TABLE "courses" ("id" integer primary key autoincrement, "name" text, "invite" text, "description" text, "image" text, "start_date" date, "end_date" date, "state" text default ('draft'), "level" text default ('start'), "created_at" text, "updated_at" text, "git" text, "telegram" text, "remote_invite" text, "site" text, "program_id" integer, "is_open" boolean default (false), "weekdays" text default (''), "mode" text default ('private'), "landing_length" text, "landing_level" text, "landing_html_description" text, "landing_short_description" text, "landing_enrollment_link" text, "landing_group_size" text, "landing_price" text, "landing_timetable" text, "default_chapter_id" integer, "learning_avatar_poster" varchar, "learning_avatar_poster_prompt" text, "learning_avatar_poster_generated_at" datetime, icon_key VARCHAR(40), current_lesson_id integer references lessons(id) on delete set null, foreign key("default_chapter_id") references program_chapters("id") on delete set null on update no action);
CREATE TABLE jobs (
    id INTEGER PRIMARY KEY ,
    queue TEXT ,
    payload text ,
    attempts smallint ,
    reserved_at integer,
    available_at integer ,
    created_at integer
);
CREATE TABLE "lesson_early_accesses" ("id" integer primary key autoincrement not null, "course_id" integer not null, "lesson_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, "source" varchar not null default 'purchase', "granted_by" integer, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("lesson_id") references lessons("id") on delete cascade on update no action, foreign key("course_id") references courses("id") on delete cascade on update no action, foreign key("granted_by") references "users"("id") on delete set null);
CREATE TABLE lesson_info (
    course_id integer,
    lesson_id integer,
    start_date date,
    id INTEGER PRIMARY KEY
);
CREATE TABLE lesson_student_stats (
    id INTEGER PRIMARY KEY ,
    course_id integer ,
    lesson_id integer ,
    student_id integer ,
    points integer DEFAULT 0 ,
    max_points integer DEFAULT 0 ,
    percent REAL DEFAULT '0' ,
    created_at TEXT,
    updated_at TEXT
);
CREATE TABLE "lessons" ("id" integer primary key autoincrement, "name" text, "description" text, "image" text, "start_date" text, "created_at" text, "updated_at" text, "is_open" boolean default (false), "sort_index" integer default (100), "sticker" text, "program_id" integer, "chapter_id" integer, "early_access_enabled" tinyint(1) not null default '0');
CREATE TABLE "market_bids" ("id" integer primary key autoincrement not null, "user_id" integer not null, "good_id" integer not null, "amount" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("good_id") references "market_goods"("id") on delete cascade);
CREATE TABLE market_deals (
    id INTEGER PRIMARY KEY ,
    user_id integer ,
    good_id integer ,
    created_at TEXT,
    updated_at TEXT,
    shipped boolean DEFAULT false ,
    shipped_by integer
, "price" integer, "source" varchar not null default 'purchase');
CREATE TABLE market_goods (
    id INTEGER PRIMARY KEY ,
    name TEXT ,
    description text ,
    price integer ,
    number integer DEFAULT 1 ,
    in_stock boolean DEFAULT true ,
    image TEXT
, "sale_type" varchar not null default 'regular', "auction_finished_at" datetime);
CREATE TABLE migrations (
    id INTEGER PRIMARY KEY ,
    migration TEXT ,
    batch integer
);
CREATE TABLE notifications (
    id uuid ,
    type TEXT ,
    notifiable_type TEXT ,
    notifiable_id bigint ,
    data text ,
    read_at TEXT,
    created_at TEXT,
    updated_at TEXT
);
CREATE TABLE "oidc_link_requests" ("id" integer primary key autoincrement not null, "user_id" integer not null, "token_hash" varchar not null, "oidc_issuer" varchar not null, "oidc_subject" varchar not null, "name" varchar not null, "email" varchar not null, "role" varchar not null, "expires_at" datetime not null, "created_at" datetime, "updated_at" datetime, "profile" text, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "planner_calendar_exceptions" ("id" integer primary key autoincrement not null, "planner_course_id" integer not null, "starts_on" date not null, "ends_on" date not null, "rule_key" varchar, "reason" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("planner_course_id") references "planner_courses"("id") on delete cascade);
CREATE TABLE "planner_calendar_slots" ("id" integer primary key autoincrement not null, "planner_course_id" integer not null, "local_date" date not null, "start_time" varchar, "duration_minutes" integer not null, "position" integer not null default '0', "origin" varchar not null default 'rule', "rule_key" varchar, "occurrence_key" varchar not null, "state" varchar not null default 'available', "reason" varchar, "created_at" datetime, "updated_at" datetime, foreign key("planner_course_id") references "planner_courses"("id") on delete cascade);
CREATE TABLE "planner_changes" ("id" integer primary key autoincrement not null, "planner_course_id" integer not null, "actor_id" integer not null, "operation_id" varchar not null, "operation_type" varchar not null, "request_hash" varchar not null, "revision_after" integer not null, "delta" text not null, "result" text not null, "undoable" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("planner_course_id") references "planner_courses"("id") on delete cascade);
CREATE TABLE "planner_course_providers" ("id" integer primary key autoincrement not null, "planner_course_id" integer not null, "provider_id" integer not null, "enabled" tinyint(1) not null default '1', "show_in_summary" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("planner_course_id") references "planner_courses"("id") on delete cascade, foreign key("provider_id") references "planner_providers"("id") on delete restrict);
CREATE TABLE "planner_courses" ("id" integer primary key autoincrement not null, "course_id" integer not null, "starts_on" date, "ends_on" date, "timezone" varchar not null default 'Europe/Moscow', "default_duration_minutes" integer not null default '90', "revision" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE TABLE "planner_deadlines" ("id" integer primary key autoincrement not null, "planner_course_id" integer not null, "resource_ref_id" integer, "title" varchar not null, "due_on" date not null, "lesson_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("planner_course_id") references "planner_courses"("id") on delete cascade, foreign key("resource_ref_id") references "planner_resource_refs"("id") on delete restrict);
CREATE TABLE "planner_providers" ("id" integer primary key autoincrement not null, "key" varchar not null, "display_name" varchar not null, "adapter_key" varchar not null, "enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "planner_resource_lesson_links" ("id" integer primary key autoincrement not null, "session_resource_id" integer not null, "lesson_id" integer not null, "relation" varchar not null default 'related', "origin" varchar not null default 'manual', "created_at" datetime, "updated_at" datetime, foreign key("session_resource_id") references "planner_session_resources"("id") on delete cascade);
CREATE TABLE "planner_resource_refs" ("id" integer primary key autoincrement not null, "provider_id" integer not null, "resource_type" varchar not null, "external_id" varchar not null, "title" varchar not null, "open_url" text, "source_revision" varchar, "public_metadata" text not null, "state" varchar not null default 'available', "last_checked_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("provider_id") references "planner_providers"("id") on delete restrict);
CREATE TABLE "planner_schedule_rules" ("id" integer primary key autoincrement not null, "planner_course_id" integer not null, "rule_key" varchar not null, "weekday" integer not null, "start_time" varchar, "duration_minutes" integer not null, "position" integer not null default '0', "valid_from" date, "valid_until" date, "active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("planner_course_id") references "planner_courses"("id") on delete cascade);
CREATE TABLE "planner_session_records" ("id" integer primary key autoincrement not null, "session_id" integer not null, "held_on" date not null, "timezone" varchar not null, "duration_minutes" integer, "note" text, "status" varchar not null default 'draft', "plan_snapshot" text not null, "confirmed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("session_id") references "planner_sessions"("id") on delete cascade);
CREATE TABLE "planner_session_resources" ("id" integer primary key autoincrement not null, "session_id" integer not null, "resource_ref_id" integer not null, "layer" varchar not null default 'plan', "sort_index" integer not null default '0', "resource_snapshot" text not null, "fact_state" varchar, "note" text, "created_at" datetime, "updated_at" datetime, foreign key("session_id") references "planner_sessions"("id") on delete cascade, foreign key("resource_ref_id") references "planner_resource_refs"("id") on delete restrict);
CREATE TABLE "planner_session_texts" ("id" integer primary key autoincrement not null, "session_id" integer not null, "layer" varchar not null default 'plan', "sort_index" integer not null default '0', "text" text not null, "fact_state" varchar, "created_at" datetime, "updated_at" datetime, foreign key("session_id") references "planner_sessions"("id") on delete cascade);
CREATE TABLE "planner_sessions" ("id" integer primary key autoincrement not null, "planner_course_id" integer not null, "calendar_slot_id" integer, "title" varchar not null default 'Занятие', "plan_note" text, "backlog_position" integer not null default '0', "pinned" tinyint(1) not null default '0', "origin" varchar not null default 'planned', "created_at" datetime, "updated_at" datetime, comment text, foreign key("planner_course_id") references "planner_courses"("id") on delete cascade, foreign key("calendar_slot_id") references "planner_calendar_slots"("id") on delete set null);
CREATE TABLE "program_chapters" ("id" integer primary key autoincrement, "program_id" integer, "name" text, "description" text, "is_scale_blocking" boolean default (false), "is_time_blocking" boolean default (false), "created_at" text, "updated_at" text, "sort_index" integer default (100));
